+    outArgs = forOp.getRegionIterArgs();
+    return UPDATE_CONDITION_INFO_SUCCESS;
+  }
+  if (auto whileOp = dyn_cast<scf::WhileOp>(loopOp)) {
+    outArgs = whileOp.getAfterArguments();
+    return UPDATE_CONDITION_INFO_SUCCESS;
+  }
