+static constexpr const char *DEBUG_TYPE = "UpdateLoopOpsLegacy";
+static constexpr int kPipeSFlagId = 15;
+#define DBGS() (llvm::dbgs() << '[' << DEBUG_TYPE << "] ")
+#define LDBG(...)                                                              \
